DELETE FROM MeterReadings WHERE UserId=1;


SELECT FuelType, YEAR(ReadingDate) as Yr, MONTH(ReadingDate) as Mo, COUNT(*) as Readings, MIN(ReadingValue) as OpenVal, MAX(ReadingValue) as CloseVal, MAX(ReadingValue)-MIN(ReadingValue) as Usage FROM MeterReadings WHERE UserId=1 GROUP BY FuelType, YEAR(ReadingDate), MONTH(ReadingDate) ORDER BY FuelType, Yr, Mo;
